                return false;

            var nukenin = new PokemonParam();
            nukenin.CopyFrom(_param.pokemonParam);
            nukenin.ChangeMonsNo(MonsNo.NUKENIN, _param.pokemonParam.GetFormNo());
            nukenin.RecoverSick();
            nukenin.RemoveItem();
            nukenin.SetMemories(Memories.CAPTURED_BALL, (uint)ItemNo.MONSUTAABOORU);
            nukenin.RemoveAllBoxMark();
            nukenin.RemoveAllRibbon();
            nukenin.ClearBankUniqueID();
            PlayerWork.playerParty.AddMember(nukenin);
            ItemWork.SubItem((int)ItemNo.MONSUTAABOORU, 1);
            ZukanWork.SetPoke(nukenin, DPData.GET_STATUS.GET);
            FieldPoketch.AddPokemonHistory(nukenin);
            return true;
        }
